 21	    Number.isFinite(done) && Number.isFinite(total) && done >= 0 && total > 0;
 22	  const ratio = hasProgress ? Math.min(1, done / total) : 0;
 23	  const percent = hasProgress ? Math.floor(ratio * 100) : undefined;
 24	  const receiving = hasProgress && done > 0;
 25	
 26	  if (presentation === "image") {
 27	    const terminalKey = status?.unavailable
 28	      ? "files.unavailable"
 29	      : status?.consent === "pending"
 30	        ? "files.approvalRequired"
 31	        : status?.consent === "declined"
 32	          ? "files.declined"
 33	          : undefined;
 34	    const imagePreparing = preparing || status?.ready || ratio === 1;
 35	    const phase = t(
 36	      terminalKey ??
 37	        (imagePreparing
 38	          ? "transfer.imagePreparing"
 39	          : receiving
 40	            ? "transfer.imageReceiving"
 41	            : "transfer.imageWaiting"),
 42	    );
 43	    const transferring = !terminalKey && !imagePreparing;
 44	    const showRing = transferring && receiving;
 45	    const PhotoIcon =
 46	      status?.unavailable || status?.consent === "declined" ? ImageOff : Image;
 47	    return (
 48	      <div className="flex min-w-0 max-w-full flex-col items-center gap-3 text-center text-card-foreground [overflow-wrap:anywhere]">
 49	        <span className="sr-only" role="status" aria-live="polite">
 50	          {phase}
 51	        </span>
