  enabled: boolean,
  mime?: string,
  options?: {
    onReadError?: (error: unknown) => void;
    retryKey?: number;
    /** Bounded reuse for ordinary previews; never enable for protected reveals. */
    reuse?: boolean;
  },
): string | null {
  const onReadError = useRef(options?.onReadError);
  useEffect(() => {
    onReadError.current = options?.onReadError;
  }, [options?.onReadError]);
  const retryKey = options?.retryKey;
  const reuse = options?.reuse === true;
  const owner = useAuth((s) => s.user?.id);
  const generation = useAuth((s) => s.generation);
  const run = useChat((s) => s.runEpoch);
  const identityEpoch = useChat((s) => s.identityEpoch);
  const ready = useChat((s) => s.ready);
  const key = JSON.stringify([
    owner,
    generation,
    run,
    identityEpoch,
    fileConv,
    mime,
    retryKey,
  ]);
  const [result, setResult] = useState<{
    key: string;
    url: string;
    ownership: { alive: boolean };
  } | null>(null);
  useEffect(() => {
    if (!enabled || !owner || !ready || !fileConv) return;
    if (reuse) observeMediaOwnership();
    const lease = captureChatOwnership();
    let alive = true;
    const ownership = { alive: true };
    let objectUrl: string | null = null;
    let releaseShared: (() => void) | undefined;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let failures = 0;
    const current = () =>
      alive && lease.current() && useChat.getState().runEpoch === run;
    const read = async () => {
      if (!current()) return;
      try {
        const readBlob = async (admitted: () => boolean) => {
          let bytes: ArrayBuffer;
          try {
            bytes = await chat.readMedia(fileConv);
          } catch (error) {
            if (!admitted()) throw error;
            bytes = await chat.readFile(fileConv);
          }
          return new Blob([bytes], mime ? { type: mime } : {});
        };
        if (reuse) {
          const shared = mediaUrls.acquire(
            key,
            readBlob,
            () => lease.current() && useChat.getState().ready,
          );
          releaseShared = shared.release;
          const url = await shared.result;
          if (current() && url) setResult({ key, url, ownership });
        } else {
          const blob = await readBlob(current);
          if (!current()) return;
          objectUrl = URL.createObjectURL(blob);
          setResult({ key, url: objectUrl, ownership });
        }
      } catch (error) {
        releaseShared?.();
        releaseShared = undefined;
        if (!current()) return;
        onReadError.current?.(error);
        const delay = Math.min(200 * 2 ** failures, 2000);

/** A file/media message body: inline media for images/small videos, else a file card with
 * a Save action. Reuses the shared MediaPreview (lazy bytes + revoked blob URLs). */
function FileBubble({
  file,
  mine,
  metadataPending,
  failed,
  sendKey,
  messageId,
  isChannel,
  isPersonal,
  readOnly,
}: {
  file: NonNullable<ChatMessage["file"]>;
  mine: boolean;
  metadataPending?: boolean;
  failed?: boolean;
  sendKey?: string;
  messageId?: string | null;
  isChannel: boolean;
  isPersonal: boolean;
  readOnly: boolean;
}) {
  const { t } = useTranslation();
  const setError = useChat((s) => s.setError);
  const savedPath = useSavedDownloads()[file.fileConv];
  const status = useFileStatus(
    savedPath ? undefined : file.fileConv || undefined,
  );
  const available = !!savedPath || !!status?.ready;
  const [saving, setSaving] = useState(false);
  const autoFailure = useAutomaticDownloads((s) => s.failures[file.fileConv]);
  const automatic = useChat(
    (s) =>
      !mine &&
      s.incomingFiles.some((entry) => entry.fileConv === file.fileConv),
  );
  const directory = isDirectoryAttachment(file.mime);
  const approvalNeeded =
    !mine && (status?.consent === "pending" || status?.consent === "declined");
  const uploadKey =
    mine && !metadataPending && !isChannel && !isPersonal
      ? messageId || undefined
      : undefined;

  const saveAs = async () => {
    const lease = captureChatOwnership();
    if (
      !lease.current() ||
      metadataPending ||
      !file.fileConv ||
      !available ||
      saving
    )
      return;
    try {
      setSaving(true);
      await saveAttachment(file, lease, {
        mode: directory ? "default" : "as",
      });
    } catch (e) {
      if (lease.current() && markUnavailableFileError(file.fileConv, e)) return;
      if (lease.current())
        setError(t("files.couldntSave", { error: errorMessage(e) }));
    } finally {
      setSaving(false);
    }
  };

  const reveal = async () => {
    if (!savedPath) return;
    const lease = captureChatOwnership();
    try {
      await revealItemInDir(savedPath);
    } catch (e) {
      if (lease.current())
        setError(t("files.couldntOpen", { error: errorMessage(e) }));
    }
  };

  const decideAttachment = createAttachmentDecision({
    captureOwnership: captureChatOwnership,
    decideAttachment: chat.decideAttachment,
    refreshAvailability: refreshFileAvailability,
    reportError: (error) =>
      setError(t("files.approvalFailed", { error: errorMessage(error) })),
  });
  const decide = (accept: boolean) => decideAttachment(file.fileConv, accept);

  // Media (image/video, sent via the media button) that is small enough to render inline:
  // show ONLY the preview. Its filename, size, and download live in the detail view that
  // opens on click (MediaPreview's lightbox) — the chat doesn't need that clutter under
  // every photo. Media that is too large to preview inline falls through to the file card
  // below, so it stays visible and savable instead of rendering an empty bubble.
  if (
    !metadataPending &&
    !approvalNeeded &&
    file.fileConv &&
    file.media &&
    withinInlineCap(file.name, file.size)
  ) {
    return (
      <div data-inline-media="" className="max-w-xs">
        <MediaPreview
          fileConv={file.fileConv}
          name={file.name}
          size={file.size}
          mime={file.mime}
          readOnly={readOnly}
        />
        {uploadKey && (
          <TransferBar
            transferKey={uploadKey}
            waitingDirection={sendKey ? "send" : undefined}
          />
        )}
      </div>
    );
  }

  // Attachment (or over-cap media): the file card IS the content — name + size + download.
  return (
    <div className="min-w-[12rem] max-w-xs">
      {!readOnly &&
        !metadataPending &&
        !approvalNeeded &&
        available &&
        isForwardedRecord(file.name, file.mime) && (
          <ForwardedRecordPreview
            fileConv={file.fileConv}
} from "@/store/chat";
import { MediaPreview } from "./MediaPreview";
import { fileGlyph } from "./mediaFile";
import { ReceiveProgress } from "./ReceiveProgress";
import { ClearHistoryButton } from "./ClearHistoryButton";
import { messageSticker, messageSummary } from "@/lib/messagePresentation";
import { usePacks } from "@/store/packs";
import { MediaSticker } from "./MediaSticker";

function HistoryMedia({ message }: { message: ChatMessage }) {
  const packs = usePacks((s) => s.packs);
  const sticker = messageSticker(message, packs);
  const file = message.file!;
  return sticker?.media ? (
    <MediaSticker
      fileConv={file.fileConv}
      mime={file.mime}
      fallback={sticker.fallback}
      label={sticker.label}
      readOnly
    />
  ) : (
    <MediaPreview
      readOnly
      fileConv={file.fileConv}
      name={file.name}
      size={file.size}
      mime={file.mime}
    />
  );
}

// Per-conversation history pulls the full backlog (the conversation stream itself caps at
// 200 for live scrolling). The backend history commands clamp to 500, which is the most a
// single page can return — so this view is complete up to the durable-store window.
const FULL_HISTORY_LIMIT = 500;
import type { Page } from "@playwright/test";
import { expect } from "../tauri-mock";
import type { Theme } from "@/lib/theme";
import { seedMarketPacks } from "./packs";

export const BOB = { account: "acc_bob_bbbb2222", device: "device_bob_2222" };
export const CAROL = {
  account: "acc_carol_cccc3333",
  device: "device_carol_3333",
};
export const CHANNEL = { id: "chan_team_dddd4444" };

export async function waitForChatShell(page: Page) {
  // Lazy chat loading includes cold transforms and coverage instrumentation.
  // Keep startup's platform budget separate from behavior assertions.
  await expect(page.getByTestId("chat-shell")).toBeVisible({
    timeout:
      process.platform === "win32" || process.env.MESH_TALK_E2E_COVERAGE === "1"
        ? 90_000
        : 15_000,
  });
}

export async function enterChatShell(page: Page, user = "tester", path = "/") {
  await page.goto(path);
  await page.getByTestId("login-tab-signin").click();
  await page.getByTestId("login-username").fill(user);
  await page.getByTestId("login-password").fill("password123");
  await page.getByTestId("login-submit").click();
  await waitForChatShell(page);
}

export async function enterChat(page: Page, user = "tester", path = "/") {
  await enterChatShell(page, user, path);
  await expect(
    page.getByTestId(`conversation-row-${BOB.account}`),
  ).toBeVisible();
}

export async function seedTheme(page: Page, theme: Theme) {
  await page.addInitScript(
    (nextTheme) => localStorage.setItem("mesh-talk-theme", nextTheme),
    theme,
  );
}

export async function openBobDm(page: Page) {
  await page.getByTestId(`conversation-row-${BOB.account}`).click();
  await expect(page.getByTestId("conversation-header")).toBeVisible();
  await expect(page.getByText("hey, welcome to the mesh")).toBeVisible();
}

export async function revealComposerTools(page: Page) {
  const trigger = page.getByTestId("composer-more-tools");
  if ((await trigger.getAttribute("aria-expanded")) !== "true") {
    await trigger.click();
  }
}

export async function seedThemeBeforeLoad(page: Page, theme: string) {
  if (!["light", "dark", "oled"].includes(theme))
    await seedMarketPacks(page, [theme]);
  await page.addInitScript((nextTheme) => {
    localStorage.setItem("mesh-talk-theme", nextTheme);
  }, theme);
}

